import {audioTargetSize,audioCopy} from '@/components/nyc-tron/ui/components/forge/audio/audio-chrome';
import {controlIdentity,useScopedControl,type ScopedControlProps} from '@/components/nyc-tron/ui/components/forge/inputs/useScopedControl';
import {ErrorMessage} from '@/components/nyc-tron/ui/components/feedback/ErrorMessage';
import { useId } from "react";
import { Platform, Pressable, Text, View, type ViewProps } from "react-native";
import { joinClasses } from "@/components/nyc-tron/ui/components/styles";
import { webToggleProps } from "@/components/nyc-tron/ui/components/forge/toggle-a11y";
import type { Audibility, audibility } from "@/components/nyc-tron/ui/components/forge/audio/mixer";
import { space, border, opacity } from '@/components/nyc-tron/ui/tokens';


export interface SoloMuteLabels {
 mute:(name:string)=>string;solo:(name:string)=>string;safe:(name:string)=>string;
 muteText:string;soloText:string;safeText:string;silencedHint:string;
}
const defaultToggleLabels:SoloMuteLabels={mute:name=>'Mute '+name,solo:name=>'Solo '+name,safe:name=>'Solo safe '+name,
 muteText:'M',soloText:'S',safeText:'Safe',silencedHint:'Silent while another channel is soloed'};

/** Props for {@linkcode SoloMuteButtons}. */
export interface SoloMuteButtonsProps extends Omit<ViewProps, "children">,ScopedControlProps {
  /** App-owned minimum interaction target. Defaults to 44 points. */
  readonly targetSize?: number;
  readonly labels?:Partial<SoloMuteLabels>;
  /** Channel name used in the accessible names, e.g. `"Mute Bass"`. */
  readonly label: string;
  /** Committed mute state. */
  readonly muted: boolean;
  /** Committed solo state. */
  readonly solo: boolean;
  /**
   * Whether the channel is heard, from {@linkcode audibility}. Pass it so a
   * channel silenced by another channel's solo shows that state on its mute
   * button. @default derived from `muted` alone
   */
  readonly audibility?: Audibility;
  /** Once per press with the requested mute state. */
  readonly onMutedCommit: (muted: boolean) => void | Promise<unknown>;
  /** Once per press with the requested solo state. */
  readonly onSoloCommit: (solo: boolean) => void | Promise<unknown>;
  /** Committed solo-safe state. @default false */
  readonly soloSafe?: boolean;
  /**
   * Once per press with the requested solo-safe state. When given, a third
   * toggle named `"Solo safe <label>"` is drawn under mute and solo.
   */
  readonly onSoloSafeCommit?: (safe: boolean) => void | Promise<unknown>;
  /** @default "row" */
  readonly direction?: "row" | "column";
  /** @default false */
  readonly disabled?: boolean;
  className?: string;
  unstyled?: boolean;
}

/**
 * Controlled mute and solo toggles for one channel. Each press requests the
 * opposite of the committed state through its commit callback; the buttons
 * keep showing the props until the app passes new ones.
 *
 * States: mute on, solo on, solo safe on, and "silent while another
 * channel is soloed", drawn as a dashed outline on the mute button. A
 * solo-safe channel keeps sounding under another channel's solo unless it
 * is muted (see {@linkcode audibility}). Group solo and mute live in
 * `MixGroupBar`.
 */
export function SoloMuteButtons({scope='SoloMuteButtons',revision=0,...props}:SoloMuteButtonsProps){
 const owner=JSON.stringify([...controlIdentity(scope,revision),props.label,props.disabled,props.disabledReason]),guard=useScopedControl(owner,props,!!props.disabled||props.disabledReason!==undefined);
 return <SoloMuteButtonsBody key={owner} {...props} actionError={guard.error} disabled={!!props.disabled||props.disabledReason!==undefined||guard.pending}
  onMutedCommit={(...args:Parameters<SoloMuteButtonsProps['onMutedCommit']>)=>guard.run('onMutedCommit',h=>h.onMutedCommit(...args))}
  onSoloCommit={(...args:Parameters<SoloMuteButtonsProps['onSoloCommit']>)=>guard.run('onSoloCommit',h=>h.onSoloCommit(...args))}
  onSoloSafeCommit={props.onSoloSafeCommit?(...args:Parameters<NonNullable<SoloMuteButtonsProps['onSoloSafeCommit']>>)=>guard.run('onSoloSafeCommit',h=>h.onSoloSafeCommit?.(...args)):undefined}
 />;
}
function SoloMuteButtonsBody({actionError,disabledReason,
  label, muted, solo, audibility, onMutedCommit, onSoloCommit, soloSafe = false, onSoloSafeCommit,
  direction = "row", disabled = false, targetSize, labels,
  className, unstyled = false, style, ...rest
}: SoloMuteButtonsProps&{actionError?:string|null}) {
  const HIT = audioTargetSize(targetSize);
  const copy = audioCopy(defaultToggleLabels, labels);
  const styled = !unstyled;
  const silenced = audibility === "silenced-by-solo";
  const hintId = useId();
  const hint = silenced && !muted ? copy.silencedHint : undefined;
  // React Native Web drops accessibilityHint; describe the button by id there.
  const webHint = Platform.OS === "web" && hint !== undefined;
  const base = "rounded-control items-center justify-center focus-visible:ring-2 focus-visible:ring-focus active:opacity-80";
  const box = { minWidth: HIT, minHeight: HIT, borderWidth: border[2], opacity: disabled ? opacity[45] : 1 };
  const muteClass = joinClasses(styled && base, styled && (muted
    ? "bg-primary border-primary"
    : silenced ? "border-text-muted bg-surface-sunken" : "border-border bg-surface-sunken"));
  const soloClass = joinClasses(styled && base, styled && (solo ? "bg-accent border-accent" : "border-border bg-surface-sunken"));
  const muteText = joinClasses(styled && "font-semibold", styled && (muted ? "text-on-primary" : silenced ? "text-text-muted" : "text-text"));
  const soloText = joinClasses(styled && "font-semibold", styled && (solo ? "text-surface-raised" : "text-text"));
  const safeClass = joinClasses(styled && base, styled && (soloSafe ? "bg-text-muted border-text-muted" : "border-border bg-surface-sunken"));
  const safeText = joinClasses(styled && "font-semibold", styled && (soloSafe ? "text-surface-raised" : "text-text"));
  const withSafe = onSoloSafeCommit !== undefined;
  return <View {...rest} {...{ className: joinClasses("gap-1", className) }}
    style={[{ flexDirection: withSafe ? "column" : direction }, style]}>
    <View style={{ flexDirection: direction, gap: space[1] }}>
    <Pressable accessibilityRole="togglebutton" accessibilityLabel={copy.mute(label)}
      accessibilityState={{ checked: muted, disabled }} {...webToggleProps(muted)}
      accessibilityHint={hint} {...(webHint ? { "aria-describedby": hintId } : {})}
      disabled={disabled} onPress={() => { void onMutedCommit(!muted); }}
      {...{ className: muteClass }}
      style={[box, silenced && !muted ? { borderStyle: "dashed" } : null]}>
      <Text {...{ className: muteText }}>{copy.muteText}</Text>
    </Pressable>
    <Pressable accessibilityRole="togglebutton" accessibilityLabel={copy.solo(label)}
      accessibilityState={{ checked: solo, disabled }} {...webToggleProps(solo)}
      disabled={disabled} onPress={() => { void onSoloCommit(!solo); }}
      {...{ className: soloClass }} style={box}>
      <Text {...{ className: soloText }}>{copy.soloText}</Text>
    </Pressable>
    </View>
    {withSafe ? <Pressable accessibilityRole="togglebutton" accessibilityLabel={copy.safe(label)}
      accessibilityState={{ checked: soloSafe, disabled }} {...webToggleProps(soloSafe)}
      disabled={disabled} onPress={() => { void onSoloSafeCommit(!soloSafe); }}
      {...{ className: safeClass }} style={[box, { paddingHorizontal: space[2] }]}>
      <Text {...{ className: safeText }}>{copy.safeText}</Text>
    </Pressable> : null}
    {webHint ? <Text nativeID={hintId}
      style={{ position: "absolute", width: 1, height: 1, overflow: "hidden", opacity: 0 }}>{hint}</Text> : null}
  <ErrorMessage message={actionError??disabledReason} unstyled={unstyled}/></View>;
}

/** App-owned interaction geometry shared by compound audio controls. */
export function audioTargetSize(value = 44): number {
  if (!Number.isFinite(value) || value < 44) throw new RangeError('Audio target must be at least 44 points');
  return value;
}
/** Undefined translations retain defaults; blank static labels cannot erase names. */
export function audioCopy<T extends object>(defaults: T, overrides?: Partial<T>): T {
  const supplied = Object.entries(overrides ?? {}).filter(([, value]) => value !== undefined);
  if (supplied.some(([, value]) => typeof value === 'string' && !value.trim())) throw new RangeError('Audio labels must be nonempty');
  return { ...defaults, ...Object.fromEntries(supplied) };
}

import {useLayoutEffect,useRef} from 'react';
import {useOwnedAction} from '@/components/nyc-tron/ui/components/shell/useOwnedAction';

/** Document identity for controlled editor tools. Native handles remain outside UI state. */
export interface ScopedControlProps {scope?:string;revision?:string|number;disabledReason?:string}
export function controlIdentity(scope:string,revision:string|number){
 if(!scope.trim()||scope.length>512||typeof revision==='number'&&!Number.isFinite(revision)||typeof revision==='string'&&revision.length>512)throw new RangeError('Invalid control identity');
 return [scope,revision] as const;
}

/** Admit one host operation and invalidate handlers at the committed boundary. */
export function useScopedControl<P>(boundary:string,props:P,disabled=false){
 const action=useOwnedAction(boundary),pending=action.pending!==null;
 const committed=useRef<{boundary:string;props:P;disabled:boolean}|null>(null);
 const admitted=useRef<symbol|null>(null);
 useLayoutEffect(()=>{committed.current={boundary,props,disabled};});
 useLayoutEffect(()=>{admitted.current=null;},[boundary]);
 useLayoutEffect(()=>()=>{committed.current=null;},[]);
 const current=()=>{const p=committed.current;return p&&p.boundary===boundary&&!p.disabled&&!pending&&!admitted.current?p.props:null;};
 const run=(id:string,operation:(props:P,signal:AbortSignal)=>unknown|Promise<unknown>)=>{
  const p=current();if(!p)return;
  const token=Symbol(id);admitted.current=token;
  return action.run(id,signal=>operation(p,signal),undefined,{pendingForAsyncOnly:true}).finally(()=>{if(admitted.current===token)admitted.current=null;});
 };
 const cancel=()=>{if(committed.current?.boundary!==boundary)return false;admitted.current=null;action.cancel();return true;};
 return {current,run,cancel,pending,pendingId:action.pending,error:action.error};
}

import { Platform } from "react-native";

/**
 * Web semantics for a toggle button. React Native's `togglebutton` role is
 * right on iOS and Android, but React Native Web passes it through as an
 * unknown ARIA role, so browsers and screen readers see no button. On web
 * this returns `role="button"` plus `aria-pressed`, which React Native Web
 * reads ahead of `accessibilityRole`. Native gets nothing, because `role`
 * would override `togglebutton` there too.
 */
export function webToggleProps(pressed: boolean): Record<string, unknown> {
  return Platform.OS === "web" ? { role: "button", "aria-pressed": pressed } : {};
}

import { createStore } from "zustand/vanilla";

/** UI request state. Abort controllers stay in the owner's closure. */
export interface ActionState { readonly pending: string | null; readonly error: string | null }
export function createActionOwner(currentScope: () => string) {
  const store = createStore<ActionState>(() => ({ pending: null, error: null }));
  let active = false;
  let current: { readonly scope: string; readonly abort: AbortController } | null = null;
  function cancel() {
    const previous = current; current = null;
    previous?.abort.abort();
  }
  return {
    store,
    activate() { cancel(); active = true; store.setState({ pending: null, error: null }); },
    deactivate() { active = false; cancel(); },
    cancel() { cancel(); store.setState({ pending: null }); },
    async run<T>(id: string, operation: (signal: AbortSignal) => T | Promise<T>, consume?: (value: T) => void, options?: { pendingForAsyncOnly?: boolean }): Promise<boolean> {
      if (!active) return false;
      cancel();
      const request = { scope: currentScope(), abort: new AbortController() };
      current = request;
      const valid = () => active && current === request && request.scope === currentScope();
      if (options?.pendingForAsyncOnly) store.setState({ error: null });
      else store.setState({ pending: id, error: null });
      try {
        if (!valid()) return false;
        const result = operation(request.abort.signal);
        let value: T;
        if (options?.pendingForAsyncOnly) {
          if (result && typeof (result as Promise<T>).then === 'function') {
            // A synchronous acknowledgement or already-resolved promise must not
            // disable (and blur) the focused control between keyboard commands.
            let settled = false;
            const completion = Promise.resolve(result).then(value => { settled = true; return value; }, error => { settled = true; throw error; });
            void Promise.resolve().then(() => { if (!settled && valid()) store.setState({ pending: id, error: null }); });
            value = await completion;
          } else value = result as T;
        } else value = await result;
        if (!valid()) return false;
        consume?.(value);
        if (!valid()) return false;
        store.setState({ pending: null });
        return true;
      } catch (error) {
        if (!valid()) return false;
        store.setState({ pending: null, error: error instanceof Error ? error.message : String(error) });
        return false;
      } finally { if (current === request) current = null; }
    },
  };
}

import { useLayoutEffect, useRef } from "react";
import { useStore } from "zustand";
import { createActionOwner } from "@/components/nyc-tron/ui/components/shell/action-owner";

/** Cancel stale requests at the committed document boundary, before new controls accept input. */
export function useOwnedAction(scope: string) {
  const committed = useRef(scope);
  const ref = useRef<ReturnType<typeof createActionOwner> | null>(null);
  ref.current ??= createActionOwner(() => committed.current);
  const owner = ref.current;
  useLayoutEffect(() => {
    committed.current = scope;
    owner.activate();
    return () => owner.deactivate();
  }, [owner, scope]);
  const state = useStore(owner.store, value => value);
  const run: typeof owner.run = (id, operation, consume, options) => committed.current === scope ? owner.run(id, operation, consume, options) : Promise.resolve(false);
  return { ...state, run, cancel: owner.cancel };
}

/**
 * Tailwind classes are merged at the APP boundary. Joining without
 * tailwind-merge avoids deleting custom typography/color utilities that
 * depend on each consumer's own @theme configuration.
 */
export function joinClasses(...items: Array<string|false|null|undefined>):string {
  return items.filter(Boolean).join(" ");
}

